<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Auditing Model Substitution in LLM APIs</title>

    <!-- Fonts: Archivo Black + Space Grotesk for technical credibility -->
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=Archivo+Black&family=Space+Grotesk:wght@400;500;600;700&display=swap" rel="stylesheet">

    <style>
        /* ===========================================
           CSS CUSTOM PROPERTIES (THEME)
           Technical/analytical dark theme
           =========================================== */
        :root {
            --bg-primary: #0a0f1c;
            --bg-secondary: #111827;
            --bg-card: #1a2332;
            --text-primary: #ffffff;
            --text-secondary: #9ca3af;
            --text-muted: #6b7280;
            --accent: #00d4ff;
            --accent-secondary: #7c3aed;
            --accent-warning: #f59e0b;
            --accent-danger: #ef4444;
            --accent-success: #10b981;
            --accent-glow: rgba(0, 212, 255, 0.2);
            --border-subtle: rgba(255, 255, 255, 0.08);

            --font-display: 'Archivo Black', sans-serif;
            --font-body: 'Space Grotesk', sans-serif;
            --title-size: clamp(1.75rem, 5vw, 3.5rem);
            --h2-size: clamp(1.25rem, 3.5vw, 2.25rem);
            --h3-size: clamp(1rem, 2.5vw, 1.5rem);
            --body-size: clamp(0.8rem, 1.5vw, 1.1rem);
            --small-size: clamp(0.7rem, 1.2vw, 0.9rem);

            --slide-padding: clamp(1.5rem, 5vw, 5rem);
            --content-gap: clamp(1rem, 2.5vw, 2rem);
            --element-gap: clamp(0.5rem, 1.5vw, 1rem);

            --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
            --duration-normal: 0.7s;
        }

        /* ===========================================
           BASE STYLES
           =========================================== */
        * { margin: 0; padding: 0; box-sizing: border-box; }

        html {
            scroll-snap-type: y mandatory;
            scroll-behavior: smooth;
            font-size: 16px;
        }

        body {
            font-family: var(--font-body);
            background: var(--bg-primary);
            color: var(--text-primary);
            line-height: 1.6;
            overflow-x: hidden;
        }

        /* ===========================================
           VIEWPORT FITTING: MANDATORY BASE STYLES
           =========================================== */
        .slide {
            width: 100vw;
            height: 100vh;
            height: 100dvh;
            overflow: hidden;
            scroll-snap-align: start;
            display: flex;
            flex-direction: column;
            position: relative;
            background: var(--bg-primary);
        }

        .slide-content {
            flex: 1;
            display: flex;
            flex-direction: column;
            justify-content: center;
            max-height: 100%;
            overflow: hidden;
            padding: var(--slide-padding);
        }

        /* ===========================================
           TYPOGRAPHY
           =========================================== */
        h1 {
            font-family: var(--font-display);
            font-size: var(--title-size);
            line-height: 1.1;
            letter-spacing: -0.02em;
            margin-bottom: var(--content-gap);
        }

        h2 {
            font-family: var(--font-display);
            font-size: var(--h2-size);
            line-height: 1.2;
            margin-bottom: var(--element-gap);
            color: var(--text-primary);
        }

        h3 {
            font-family: var(--font-body);
            font-size: var(--h3-size);
            font-weight: 600;
            line-height: 1.3;
            margin-bottom: var(--element-gap);
        }

        p, li {
            font-size: var(--body-size);
            line-height: 1.5;
            color: var(--text-secondary);
        }

        .subtitle {
            font-size: clamp(1rem, 2vw, 1.5rem);
            color: var(--text-secondary);
            font-weight: 400;
            max-width: 800px;
        }

        .tagline {
            font-size: var(--small-size);
            color: var(--accent);
            text-transform: uppercase;
            letter-spacing: 0.15em;
            margin-bottom: var(--element-gap);
        }

        /* ===========================================
           ANIMATIONS
           =========================================== */
        .reveal {
            opacity: 0;
            transform: translateY(25px);
            transition: opacity var(--duration-normal) var(--ease-out-expo),
                        transform var(--duration-normal) var(--ease-out-expo);
        }

        .slide.visible .reveal {
            opacity: 1;
            transform: translateY(0);
        }

        .reveal:nth-child(1) { transition-delay: 0.05s; }
        .reveal:nth-child(2) { transition-delay: 0.15s; }
        .reveal:nth-child(3) { transition-delay: 0.25s; }
        .reveal:nth-child(4) { transition-delay: 0.35s; }
        .reveal:nth-child(5) { transition-delay: 0.45s; }
        .reveal:nth-child(6) { transition-delay: 0.55s; }

        .reveal-delay-1 { transition-delay: 0.3s !important; }
        .reveal-delay-2 { transition-delay: 0.5s !important; }
        .reveal-delay-3 { transition-delay: 0.7s !important; }

        /* ===========================================
           SLIDE LAYOUTS
           =========================================== */
        .slide-title {
            background: linear-gradient(135deg, var(--bg-primary) 0%, var(--bg-secondary) 100%);
        }

        .slide-title::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background:
                radial-gradient(ellipse at 20% 80%, rgba(0, 212, 255, 0.08) 0%, transparent 50%),
                radial-gradient(ellipse at 80% 20%, rgba(124, 58, 237, 0.08) 0%, transparent 50%);
            pointer-events: none;
        }

        .title-content {
            position: relative;
            z-index: 1;
            max-width: 1000px;
        }

        .title-content .subtitle {
            margin-top: var(--content-gap);
        }

        .paper-ref {
            margin-top: var(--content-gap);
            padding: var(--element-gap) var(--content-gap);
            background: rgba(0, 212, 255, 0.1);
            border: 1px solid rgba(0, 212, 255, 0.2);
            border-radius: 8px;
            font-size: var(--small-size);
            color: var(--accent);
            display: inline-block;
        }

        /* ===========================================
           CONTENT CARDS
           =========================================== */
        .content-grid {
            display: grid;
            gap: var(--content-gap);
            max-width: 1200px;
            margin: 0 auto;
            width: 100%;
        }

        .content-grid.two-col {
            grid-template-columns: repeat(2, 1fr);
        }

        .content-grid.three-col {
            grid-template-columns: repeat(3, 1fr);
        }

        .card {
            background: var(--bg-card);
            border: 1px solid var(--border-subtle);
            border-radius: 12px;
            padding: var(--content-gap);
        }

        .card-accent {
            border-left: 3px solid var(--accent);
        }

        .card-purple {
            border-left: 3px solid var(--accent-secondary);
        }

        .card-warning {
            border-left: 3px solid var(--accent-warning);
        }

        .card-danger {
            border-left: 3px solid var(--accent-danger);
        }

        .card-success {
            border-left: 3px solid var(--accent-success);
        }

        /* ===========================================
           DATA TABLE
           =========================================== */
        .data-table {
            width: 100%;
            border-collapse: collapse;
            font-size: var(--small-size);
            margin: var(--element-gap) 0;
        }

        .data-table th,
        .data-table td {
            padding: clamp(0.4rem, 1vw, 0.75rem) clamp(0.5rem, 1.5vw, 1rem);
            text-align: left;
            border-bottom: 1px solid var(--border-subtle);
        }

        .data-table th {
            font-weight: 600;
            color: var(--text-primary);
            background: rgba(0, 212, 255, 0.05);
            font-size: var(--small-size);
            text-transform: uppercase;
            letter-spacing: 0.05em;
        }

        .data-table td {
            color: var(--text-secondary);
        }

        .data-table tr:hover td {
            background: rgba(255, 255, 255, 0.02);
        }

        .data-table .model-name {
            font-weight: 500;
            color: var(--text-primary);
        }

        .data-table .fp8-indicator {
            color: var(--accent-warning);
            font-size: 0.85em;
        }

        .score-diff {
            color: var(--accent-danger);
            font-size: 0.85em;
        }

        .score-same {
            color: var(--accent-success);
            font-size: 0.85em;
        }

        /* ===========================================
           COMPARISON MATRIX
           =========================================== */
        .matrix-table {
            width: 100%;
            border-collapse: collapse;
            font-size: var(--small-size);
        }

        .matrix-table th,
        .matrix-table td {
            padding: clamp(0.5rem, 1.5vw, 1rem);
            text-align: left;
            border: 1px solid var(--border-subtle);
        }

        .matrix-table th {
            background: var(--bg-card);
            font-weight: 600;
            color: var(--text-primary);
        }

        .matrix-table td {
            background: rgba(17, 24, 39, 0.5);
            color: var(--text-secondary);
        }

        .matrix-table .method-type {
            font-weight: 600;
            color: var(--accent);
        }

        .badge {
            display: inline-block;
            padding: 0.2em 0.6em;
            border-radius: 4px;
            font-size: 0.75em;
            font-weight: 600;
            text-transform: uppercase;
            letter-spacing: 0.03em;
        }

        .badge-danger {
            background: rgba(239, 68, 68, 0.15);
            color: var(--accent-danger);
        }

        .badge-warning {
            background: rgba(245, 158, 11, 0.15);
            color: var(--accent-warning);
        }

        .badge-success {
            background: rgba(16, 185, 129, 0.15);
            color: var(--accent-success);
        }

        /* ===========================================
           DIAGRAM/STATS
           =========================================== */
        .stat-grid {
            display: grid;
            grid-template-columns: repeat(4, 1fr);
            gap: var(--element-gap);
            margin: var(--content-gap) 0;
        }

        .stat-card {
            background: var(--bg-card);
            border: 1px solid var(--border-subtle);
            border-radius: 8px;
            padding: var(--element-gap);
            text-align: center;
        }

        .stat-value {
            font-family: var(--font-display);
            font-size: clamp(1.5rem, 3vw, 2.5rem);
            color: var(--accent);
            line-height: 1;
            margin-bottom: 0.25em;
        }

        .stat-label {
            font-size: var(--small-size);
            color: var(--text-muted);
            text-transform: uppercase;
            letter-spacing: 0.1em;
        }

        .flow-diagram {
            display: flex;
            align-items: center;
            justify-content: center;
            gap: var(--element-gap);
            margin: var(--content-gap) 0;
            flex-wrap: wrap;
        }

        .flow-box {
            background: var(--bg-card);
            border: 1px solid var(--border-subtle);
            border-radius: 8px;
            padding: var(--element-gap) clamp(0.75rem, 2vw, 1.5rem);
            text-align: center;
        }

        .flow-box.highlight {
            border-color: var(--accent);
            box-shadow: 0 0 20px var(--accent-glow);
        }

        .flow-arrow {
            color: var(--text-muted);
            font-size: clamp(1.2rem, 2vw, 1.5rem);
        }

        /* ===========================================
           IMAGE SLIDES
           =========================================== */
        .image-container {
            display: flex;
            justify-content: center;
            align-items: center;
            margin: var(--element-gap) 0;
        }

        .slide-image {
            max-width: 100%;
            max-height: min(45vh, 400px);
            object-fit: contain;
            border-radius: 8px;
            border: 1px solid var(--border-subtle);
        }

        .image-caption {
            text-align: center;
            font-size: var(--small-size);
            color: var(--text-muted);
            margin-top: var(--element-gap);
            font-style: italic;
        }

        /* ===========================================
           LIST STYLES
           =========================================== */
        .bullet-list {
            list-style: none;
            display: flex;
            flex-direction: column;
            gap: var(--element-gap);
        }

        .bullet-list li {
            padding-left: 1.5em;
            position: relative;
        }

        .bullet-list li::before {
            content: '▸';
            position: absolute;
            left: 0;
            color: var(--accent);
        }

        .numbered-list {
            list-style: none;
            counter-reset: item;
            display: flex;
            flex-direction: column;
            gap: var(--element-gap);
        }

        .numbered-list li {
            counter-increment: item;
            padding-left: 2em;
            position: relative;
        }

        .numbered-list li::before {
            content: counter(item);
            position: absolute;
            left: 0;
            width: 1.5em;
            height: 1.5em;
            background: var(--accent);
            color: var(--bg-primary);
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            font-weight: 700;
            font-size: var(--small-size);
        }

        /* ===========================================
           TAKEAWAYS
           =========================================== */
        .takeaway-item {
            display: flex;
            align-items: flex-start;
            gap: var(--element-gap);
            padding: var(--element-gap);
            background: var(--bg-card);
            border-radius: 8px;
            border-left: 3px solid var(--accent);
        }

        .takeaway-number {
            font-family: var(--font-display);
            font-size: clamp(1.2rem, 2.5vw, 1.75rem);
            color: var(--accent);
            line-height: 1;
            flex-shrink: 0;
        }

        .takeaway-text {
            font-size: var(--body-size);
            color: var(--text-secondary);
        }

        /* ===========================================
           NAVIGATION
           =========================================== */
        .nav-dots {
            position: fixed;
            right: clamp(0.75rem, 2vw, 1.5rem);
            top: 50%;
            transform: translateY(-50%);
            display: flex;
            flex-direction: column;
            gap: 8px;
            z-index: 100;
        }

        .nav-dot {
            width: 10px;
            height: 10px;
            border-radius: 50%;
            background: var(--text-muted);
            opacity: 0.3;
            cursor: pointer;
            transition: all 0.3s ease;
        }

        .nav-dot.active {
            background: var(--accent);
            opacity: 1;
        }

        .nav-dot:hover {
            opacity: 0.8;
            transform: scale(1.2);
        }

        .progress-bar {
            position: fixed;
            top: 0;
            left: 0;
            height: 3px;
            background: linear-gradient(90deg, var(--accent), var(--accent-secondary));
            width: 0%;
            z-index: 100;
            transition: width 0.3s ease;
        }

        .slide-number {
            position: fixed;
            bottom: clamp(0.75rem, 2vw, 1.5rem);
            right: clamp(0.75rem, 2vw, 1.5rem);
            font-size: var(--small-size);
            color: var(--text-muted);
            z-index: 100;
        }

        /* ===========================================
           RESPONSIVE BREAKPOINTS
           =========================================== */
        @media (max-height: 700px) {
            :root {
                --slide-padding: clamp(1rem, 3vw, 2.5rem);
                --content-gap: clamp(0.75rem, 1.5vw, 1.25rem);
                --element-gap: clamp(0.3rem, 1vw, 0.75rem);
                --title-size: clamp(1.5rem, 4vw, 2.5rem);
            }
        }

        @media (max-height: 600px) {
            :root {
                --slide-padding: clamp(0.75rem, 2.5vw, 1.5rem);
                --title-size: clamp(1.25rem, 3.5vw, 2rem);
                --h2-size: clamp(1rem, 3vw, 1.5rem);
            }
            .nav-dots { display: none; }
        }

        @media (max-width: 900px) {
            .content-grid.two-col,
            .content-grid.three-col {
                grid-template-columns: 1fr;
            }
            .stat-grid {
                grid-template-columns: repeat(2, 1fr);
            }
        }

        @media (max-width: 600px) {
            .content-grid {
                grid-template-columns: 1fr;
            }
            .stat-grid {
                grid-template-columns: 1fr;
            }
            .nav-dots { display: none; }
        }

        @media (prefers-reduced-motion: reduce) {
            *, *::before, *::after {
                animation-duration: 0.01ms !important;
                transition-duration: 0.2s !important;
            }
            html { scroll-behavior: auto; }
        }
    </style>
</head>
<body>
    <!-- Progress Bar -->
    <div class="progress-bar"></div>

